package live.linghe.privateinput;
import java.io.*;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import org.json.*;
/** Strict public cloud canonical form: Unicode/slash unescaped, exact integers. */
final class CloudLearningCanonical {
 static String encode(Object value)throws Exception{StringBuilder out=new StringBuilder();write(value,out,0);return out.toString();}
 private static void quote(String text,StringBuilder out)throws Exception{LosslessJson.unicode(text);out.append('"');for(int i=0;i<text.length();i++){char c=text.charAt(i);switch(c){case '"':out.append("\\\"");break;case '\\':out.append("\\\\");break;case '\b':out.append("\\b");break;case '\f':out.append("\\f");break;case '\n':out.append("\\n");break;case '\r':out.append("\\r");break;case '\t':out.append("\\t");break;default:if(c<32)out.append(String.format(Locale.ROOT,"\\u%04x",(int)c));else out.append(c);}}out.append('"');}
 private static void write(Object value,StringBuilder out,int depth)throws Exception{if(depth>24)throw new IOException("cloud JSON depth");if(value==null||value==JSONObject.NULL){out.append("null");return;}if(value instanceof JSONObject){JSONObject object=(JSONObject)value;List<String> keys=new ArrayList<>();Iterator<String> names=object.keys();while(names.hasNext())keys.add(names.next());Collections.sort(keys);out.append('{');boolean comma=false;for(String key:keys){if(comma)out.append(',');comma=true;quote(key,out);out.append(':');write(object.get(key),out,depth+1);}out.append('}');return;}if(value instanceof JSONArray){JSONArray array=(JSONArray)value;out.append('[');for(int i=0;i<array.length();i++){if(i>0)out.append(',');write(array.get(i),out,depth+1);}out.append(']');return;}if(value instanceof String){quote((String)value,out);return;}if(value instanceof Boolean){out.append(value);return;}if(value instanceof Number){BigInteger integer=LosslessJson.unsigned(value);out.append(integer.toString());return;}throw new IOException("cloud JSON value");}
 static String hash(Object value)throws Exception{byte[] bytes=encode(value).getBytes(StandardCharsets.UTF_8);StringBuilder out=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))out.append(String.format(Locale.ROOT,"%02x",b&255));return out.toString();}
}
